/// Trusts the platform's roots. Without any, requests fail with a TLS error rather than
/// the client panicking on creation.
#[cfg(feature = "rustls-tls")]
pub(crate) fn make_connector() -> hyper_rustls::HttpsConnector<HttpConnector> {
    let provider = rustls::crypto::CryptoProvider::get_default()
        .cloned()
        .unwrap_or_else(|| Arc::new(rustls::crypto::ring::default_provider()));
    let builder = hyper_rustls::HttpsConnectorBuilder::new();
    let builder = match builder.with_provider_and_native_roots(provider.clone()) {
        Ok(builder) => builder,
        Err(_) => hyper_rustls::HttpsConnectorBuilder::new().with_tls_config(
            rustls::ClientConfig::builder_with_provider(provider)
                .with_safe_default_protocol_versions()
                .expect("the default provider supports the default protocol versions")
                .with_root_certificates(rustls::RootCertStore::empty())
                .with_no_client_auth(),
        ),
    };
    let builder = builder.https_or_http();
    #[cfg(feature = "http1")]
    let builder = builder.enable_http1();
    #[cfg(feature = "http2")]
    let builder = builder.enable_http2();

    let mut http = HttpConnector::new();
    http.enforce_http(false);
    builder.wrap_connector(http)
}
